insert into public.about (id, paragraphs, image_1, image_2, counter_value, counter_label, quote, quote_author)
values (1, '[{"en":"Mehmet Oglu began in 1928 as a single charcoal spit beside the Grand Bazaar. Four generations later the recipe is unchanged: lamb and veal hand-stacked each dawn, roasted slowly over oak embers and carved paper-thin to order.","tr":"Mehmet Oglu, 1928''de Kapalıçarşı''nın yanında tek bir kömür şişiyle başladı. Dört kuşak sonra tarif aynı: her sabah elle dizilen kuzu ve dana, meşe korunda ağır ağır pişer ve sipariş üzerine kâğıt inceliğinde kesilir."},{"en":"Our İskender is served the Bursa way — over hand-torn pide, drowned in tomato sauce and finished tableside with sizzling brown butter. Nothing arrives pre-cut, nothing arrives lukewarm.","tr":"İskender''imiz Bursa usulü sunulur — elle bölünmüş pide üzerine, domates soslu ve masada kızgın tereyağıyla tamamlanmış. Hiçbir şey önceden kesilmez, hiçbir şey ılık gelmez."}]'::jsonb, '/images/brand/menu-cover-iskender-plate.webp', '/images/brand/poster-heritage.webp', 1928, '{"en":"Serving İstanbul since","tr":"İstanbul''a hizmet veriyoruz"}'::jsonb, '{"en":"“The spit turns the same way it did in my grandfather''s day. Only the city around it has changed.”","tr":"“Şiş, dedemin zamanındaki gibi dönüyor. Değişen sadece etrafındaki şehir.”"}'::jsonb, 'Mehmet Oğlu, 4th generation')
on conflict (id) do update set paragraphs = excluded.paragraphs, image_1 = excluded.image_1, image_2 = excluded.image_2,
  counter_value = excluded.counter_value, counter_label = excluded.counter_label, quote = excluded.quote, quote_author = excluded.quote_author;

